    raw = gzip.decompress(base64.b85decode(payload))
    if hashlib.sha256(raw).hexdigest() != 'cbd23c6a50ceda73cfdaa312b0b374cc505d4d698f41a3e52e998726bcab6829':
        raise ValueError('Cell36 archived input changed; no silent replacement.')
    data = json.loads(raw)
    counters = Counter()
    errors = Counter()
    rr = np.arange(3)
    basis = tuple(product(range(3), repeat=2))
    reflected = (1, 0, 2)
    identity9 = np.eye(9, dtype=complex)
    diag_basis = np.eye(9, dtype=complex)[:, [0, 4, 8]]
    code_projector = diag_basis @ diag_basis.conj().T
    F3 = np.exp(2j*np.pi*rr[:, None]*rr[None, :]/3)/sqrt(3)
    words = diag_basis @ F3   # column k: sum_r omega^(rk)|rr>/sqrt(3).
    phases = (27, 81)

    def check(ok, message):
        if not ok:
            raise AssertionError(message)

    def close(a, b, label, tol=2e-12):
        error = float(np.max(np.abs(np.asarray(a)-np.asarray(b))))
        errors[label] = max(errors[label], error)
        check(error < tol, f'{label}: {error}')

    def jable(x):
        if isinstance(x, complex): return {'real': float(x.real), 'imag': float(x.imag)}
        if isinstance(x, Fraction): return str(x)
        if isinstance(x, np.ndarray): return jable(x.tolist())
        if isinstance(x, np.generic): return jable(x.item())
        if isinstance(x, dict): return {str(k): jable(v) for k, v in x.items()}
        if isinstance(x, (tuple, list)): return [jable(v) for v in x]
        return x

    def incidence(paths, entry=False):
        values = []
        for side in (paths[:2], paths[2:]):
            c = Counter()
            for root, tokens in side:
                c.update(tuple(t) if entry else t[0] for t in tokens)
            values.append(c)
        return values

    def characters(paths, entry=False):
        # Each row is the exact integer generator on the 9 computational states.
        a, b = incidence(paths, entry)
        regs = sorted({z for root, tok in paths for z, e in tok})
        rows = []
        for z in regs:
            row = []
            for r, s in basis:
                if not entry:
                    value = a[z]*r-b[z]*s
                else:
                    value = sum(a[(z,e)]*(reflected[r] if e else r)
                                - b[(z,e)]*(reflected[s] if e else s) for e in (0,1))
                row.append(value)
            rows.append(row)
        return regs, np.asarray(rows, dtype=np.int64)

    def canonical_relation(paths):
        sides = [tuple(sorted((int(root), tuple(tuple(t) for t in tok))
                              for root,tok in side)) for side in (paths[:2],paths[2:])]
        return tuple(sorted(sides))

    # 1. All saved representative assemblies; do not promote these to a new exhaustive census.
    examples = []
    distinct = set()
    for ex in data['examples']:
        world, cp, paths = ex['world'], ex['checkpoint'], ex['paths']
        check(len(set(tuple(z for z,e in p[1]) for p in paths)) == 4,
              'The four supports must be distinct.')
        for root, tokens in paths:
            check(root in (0,1), 'Nonprimitive path root')
            parent = root
            for z,e in tokens:
                card = data['cards'][world][str(z)]
                check(card['parents'][e] == parent, 'Broken placement path')
                check(0 < card['write_step'] <= cp['step'] and z < cp['n'],
                      'Unrecorded or future register')
                parent = z
                counters['validated_path_tokens'] += 1
        left, right = incidence(paths)
        elt, ert = incidence(paths, True)
        check(left == right, 'Archived register balance missing')
        token_balanced = elt == ert
        check(token_balanced == ex['entry_token_balance'], 'Archived token-balance flag')
        distinct.add((world,canonical_relation(paths)))
        status = {}
        for entry in (False, True):
            regs, h = characters(paths, entry)
            protected = bool(np.all(h[:, [0,4,8]] == 0))
            check(protected == (not entry or token_balanced), 'Unexpected code character')
            status['entry_sensitive' if entry else 'primary'] = protected
            for Q in phases:
                for row in h:
                    u = np.exp(2j*np.pi*(row%Q)/Q)
                    # Check the complete 3x3 logical matrix-unit basis, not populations alone.
                    if protected:
                        close(u[[0,4,8],None]*u[[0,4,8]].conj()[None,:],
                              np.ones((3,3)), 'protected_matrix_units')
                        counters['protected_matrix_unit_checks'] += 9
                    counters['exact_register_generators'] += 1
        examples.append(dict(world=world,epoch_target=ex['epoch_target'],cohort=ex['cohort'],
                             length=ex['length'],kind=ex['kind'],token_balanced=token_balanced,
                             code_protected=status))
    primary = data['primary']
    paths = primary['paths']
    regs, hprimary = characters(paths)
    _, hentry = characters(paths, True)
    check(np.all(hentry[:, [0,4,8]] == 0), 'Primary example must be entry balanced')
    hbyreg = {False: dict(zip(regs,hprimary)), True: dict(zip(regs,hentry))}
    close(words.conj().T@words,np.eye(3),'orthogonal_words')

    # 2. Complete finite classical transition audit at the actual 19-object checkpoint.
    # This independent implementation is validated against the original constructor in the bundle.
    start = data['primary_state']
    n, forced, relief = start['n'],start['F'],start['P']
    parents = [None if row[0] < 0 else tuple(row[:2]) for row in start['nodes']]
    chains = [row[2] for row in start['nodes']]
    existing = {p for p in parents if p is not None}
    recorded = {p for pair in existing for p in pair}
    anc = []
    for z,pair in enumerate(parents):
        if pair is None: anc.append({z})
        else:
            check(pair[0]<pair[1]<z and chains[z]==sum(chains[v] for v in pair),'Bad native parentage')
            anc.append(anc[pair[0]]|anc[pair[1]]|{z})
    check(recorded == {z for z,row in enumerate(start['nodes']) if row[6]>0}, 'Recorded-mask mismatch')
    R, q = forced+n, min(3,forced+n)
    denominator = comb(R,q)
    native_rows=[]
    native_histograms=[Counter() for _ in range(3)]
    weighted_sum=0
    native_noise_max=0.0
    for s in range(q+1):
        multiplicity=comb(forced,q-s)
        for W in combinations(range(n),s):
            f=q-s;fm=forced-f;pm=relief+2*f
            quota=2*((max(1,pm//6)+1)//2)
            v=min(quota,start['H'],fm,pm) if fm>=3 and pm>=6 else 0
            pairs=[pair for pair in combinations(W,2) if pair not in existing]
            hits=Counter(z for a,b in pairs for z in (anc[a]|anc[b]))
            repeat=sum(2*(2*chains[z]-2)*k for z,k in hits.items())
            premium=sum(9*(2*chains[z]-2) for z in hits if z not in recorded)
            cost=repeat+premium
            row=dict(served=W,forced_served=f,new_pairs=pairs,cost=cost,
                     repeat_part=repeat,first_use_premium=premium,relief_removed=v,
                     next_n=n+len(pairs),next_F=fm-v+cost,next_P=pm-v,
                     next_tau=start['tau']+s,draw_multiplicity=multiplicity)
            native_rows.append(row);weighted_sum+=multiplicity
            # Native successor law contains no encoded word/complex amplitude argument.
            # The attached storage operation is separately verified for each word.
            h=sum((hbyreg[False][z] for z in W if z in hbyreg[False]),np.zeros(9,dtype=int))
            u=np.exp(2j*np.pi*(h%27)/27)
            for k in range(3):
                native_histograms[k][(row['next_n'],row['next_F'],row['next_P'],cost)] += multiplicity
                error=float(np.max(abs(u*words[:,k]-words[:,k])))
                native_noise_max=max(native_noise_max,error)
                check(error<1e-13,'A legal native event changed the protected word')
                counters['native_word_event_checks']+=1
            counters['native_maintenance_subsets']+=1
    check(weighted_sum==denominator,'Native transition normalization')
    check(native_histograms[0]==native_histograms[1]==native_histograms[2], 'Classical state dependence')
    contact=next(row for row in native_rows if row['served']==(10,11))
    check(contact['new_pairs']==[(10,11)],'Declared recorded-endpoint contact already exists')

    # Read-only late-event projection: full source node table was searched for the
    # selected pair; its old ancestry is inside the included complete prefix.
    # This is sufficient for this ONE two-parent/one-forced draw, not a late simulator.
    late_projection=data['late_contact_projection']; lcp=late_projection['checkpoint']
    check(late_projection['served']==[10,11], 'Late comparison changed')
    check([r[1:3] if r[1]>=0 else None for r in late_projection['old_prefix_nodes']]
          == [list(p) if p is not None else None for p in parents], 'Old parentage changed')
    late_used=anc[10]|anc[11]
    late_recorded={r[0] for r in late_projection['old_prefix_nodes'] if 0<r[7]<=lcp['step']}
    late_cost=0 if late_projection['pair_child'] is not None else sum(
        (2 if z in late_recorded else 11)*(2*chains[z]-2) for z in late_used)
    late_contact=dict(tau=lcp['tau'],n=lcp['n'],F=lcp['F'],P=lcp['P'],
        served=(10,11),forced_served=1,pair_child_before=late_projection['pair_child'],
        cost=late_cost,new_births=int(late_projection['pair_child'] is None),
        next_F=lcp['F']-1+late_cost,codeword_costs=(late_cost,)*3,
        analysis_kind='exact one-event sufficient-state projection, not a new late simulation')

    # 3. Existing Fourier readout, with an explicit projective state-update assumption.
    # The source fixes probabilities, but NOT a unique post-measurement instrument.
    # Rank-one local projectors give one natural implementation, not the only possible one.
    products=[];outcomes=[]
    for a,b in product(range(3),repeat=2):
        av=np.exp(-2j*np.pi*rr*a/3)/sqrt(3)
        bv=np.exp(+2j*np.pi*rr*b/3)/sqrt(3)
        products.append(np.kron(av,bv));outcomes.append((a,b))
    products=np.asarray(products).T
    close(products.conj().T@products,np.eye(9),'Fourier_PVM')
    readout=[]
    for k in range(3):
        weights=abs(products.conj().T@words[:,k])**2
        confusion=np.array([sum(p for p,(a,b) in zip(weights,outcomes) if (b-a)%3==v) for v in range(3)])
        posterior=sum(p*np.outer(v,v.conj()) for p,v in zip(weights,products.T))
        fidelity=float(np.vdot(words[:,k],posterior@words[:,k]).real)
        retained=float(np.trace(code_projector@posterior).real)
        pt=posterior.reshape(3,3,3,3).transpose(0,3,2,1).reshape(9,9)
        neg=float(np.abs(np.linalg.eigvalsh(pt)[np.linalg.eigvalsh(pt)<0]).sum())
        close(confusion,np.eye(3)[k],'perfect_joint_decode')
        close([fidelity,retained,neg],[1/3,1/3,0],'projective_memory_backaction')
        readout.append(dict(word=k,decoded_distribution=confusion,
                            nonselective_density=posterior,fidelity=fidelity,
                            protected_space_weight=retained,negativity=neg))
        counters['projective_readout_words']+=1
    local_marginal=np.eye(3)/3
    for k in range(3):
        rho=np.outer(words[:,k],words[:,k].conj()).reshape(3,3,3,3)
        close(np.trace(rho,axis1=1,axis2=3),local_marginal,'local_blindness')
        close(np.trace(rho,axis1=0,axis2=2),local_marginal,'local_blindness')

    # Existing single-factor phase gate gives a logical label shift; still a commanded gate.
    Z_A=np.diag(np.kron(np.exp(2j*np.pi*rr/3),np.ones(3)))
    logical_shift=words.conj().T@Z_A@words
    expected_shift=np.roll(np.eye(3),1,axis=0)
    close(logical_shift,expected_shift,'logical_label_update')
    for h in hprimary:
        u=np.exp(2j*np.pi*h/27)
        close(u[:,None]*(Z_A@words),Z_A@words,'updated_word_stays_protected')

    # 4. NEW FEASIBILITY MODEL: coherent probe-controlled common cyclic shift.
    # Qutrit probe is extra; this is not obtained by calling add_batch().
    def controlled_shift(which):
        result=np.zeros((27,27),complex)
        for a,b,m in product(range(3),repeat=3):
            aa=(a+m)%3 if which in ('A','AB') else a
            bb=(b+m)%3 if which in ('B','AB') else b
            result[9*aa+3*bb+m,9*a+3*b+m]=1
        return result
    CA,CB,V=(controlled_shift(which) for which in ('A','B','AB'))
    probe_fourier=np.kron(identity9,F3)
    Wmeter=probe_fourier@V@probe_fourier
    close(CB@CA,V,'split_control_product')
    close(Wmeter.conj().T@Wmeter,np.eye(27),'probe_unitarity')
    # Same COARSE three-outcome POVM as reading local Fourier outcomes and reporting
    # their difference. The state updates differ: fine local PVM vs coherent coarse PVM.
    coarse_projectors=[]
    for k in range(3):
        coarse=sum(np.outer(v,v.conj()) for v,(a,b) in zip(products.T,outcomes) if (b-a)%3==k)
        K=Wmeter.reshape(9,3,9,3)[:,k,:,0]
        close(K,coarse,'same_coarse_measurement_effects')
        close(coarse@coarse,coarse,'coarse_projector_idempotent')
        close(np.trace(coarse),3,'coarse_rank')
        coarse_projectors.append(coarse)
        counters['coarse_instrument_effects']+=1
    close(sum(coarse_projectors),identity9,'coarse_completeness')
    word_probe_basis=np.kron(words,np.eye(3))
    zero=np.array([1,0,0],complex)
    source_inputs=np.stack([np.kron(words[:,k],zero) for k in range(3)],axis=1)
    ideal_outputs=Wmeter@source_inputs
    qnd=[]
    for k in range(3):
        target=np.kron(words[:,k],np.eye(3)[:,k])
        close(ideal_outputs[:,k],target,'nondestructive_label_read')
        qnd.append(dict(word=k,meter_correct_probability=1.0,memory_fidelity=1.0,
                        code_space_weight=1.0))
        counters['ideal_meter_words']+=1
    # Any logical superposition stays in C, but tracing out the correlated probe
    # does NOT preserve all logical coherences. Use a fixed, non-basis input |00>.
    initial=np.zeros(9,complex);initial[0]=1
    entangled=Wmeter@np.kron(initial,zero)
    out=entangled.reshape(9,3)
    reduced=out@out.conj().T
    close(reduced,code_projector/3,'discarded_probe_dephases_logical_superposition')
    coherent_return=Wmeter.conj().T@entangled
    close(coherent_return,np.kron(initial,zero),'coherent_probe_inverse')
    # Same labels can be read again by another clean ideal probe.
    repeat=[]
    for k in range(3):
        state=np.einsum('a,b,c->abc',words[:,k],np.eye(3)[:,k],zero)
        mapped=np.einsum('amcn,cbn->abm',Wmeter.reshape(9,3,9,3),state)
        target=np.einsum('a,b,c->abc',words[:,k],np.eye(3)[:,k],np.eye(3)[:,k])
        close(mapped,target,'second_probe_same_label')
        repeat.append(dict(word=k,agreement_probability=1.0))

    # 5. One background service between the two local controlled shifts.
    # All three words and all residues are retained. No gate time or depth scan to optimize success.
    def interrupted(h,Q):
        u=np.exp(2j*np.pi*(np.asarray(h,dtype=np.int64)%Q)/Q)
        storage=np.kron(np.diag(u),np.eye(3))
        circuit=probe_fourier@CB@storage@CA@probe_fourier
        result=circuit@source_inputs
        amps=word_probe_basis.conj().T@result
        distribution=abs(amps.reshape(3,3,3))**2   # memory word, meter word, input word
        close(distribution.sum(axis=(0,1)),np.ones(3),'split_gap_code_space')
        metrics=[]
        for k in range(3):
            p=distribution[:,:,k]
            metrics.append(dict(memory_fidelity=float(p[k,:].sum()),
                                meter_correct_probability=float(p[:,k].sum()),
                                both_correct_probability=float(p[k,k]),
                                code_space_weight=float(p.sum())))
        counters['interrupted_circuits']+=1
        return dict(metrics=metrics,joint_label_probabilities=distribution)

    # A code-support metric alone misses logical errors: the completed split sequence returns to C.
    gap_tables={}
    for Q in phases:
        gap_tables[Q]={}
        for entry in (False,True):
            mode='entry_sensitive' if entry else 'primary'
            singles={z:interrupted(hbyreg[entry][z],Q) for z in regs}
            # Primary native all-subset audit and a later same-structure context.
            checkpoints=[start, data['worlds']['H0_s20350920']['checkpoints']['4194304']]
            byage=[]
            for cp in checkpoints:
                pool=cp['n']+cp['F'];qq=min(3,pool);den=comb(pool,qq)
                # Marginalize all requests outside the FIXED union, including forced work.
                # Each subset of the union has exactly C(pool-u, q-j) compatible draws.
                weighted=np.zeros((3,3,3),float);norm=Fraction(0)
                infidelity=np.zeros(3);meter_error=np.zeros(3);joint_error=np.zeros(3)
                for j in range(min(qq,len(regs))+1):
                    mult=comb(pool-len(regs),qq-j)
                    if not mult:continue
                    for selected in combinations(regs,j):
                        h=sum((hbyreg[entry][z] for z in selected),np.zeros(9,dtype=int))
                        d=interrupted(h,Q);wt=Fraction(mult,den);norm+=wt
                        weighted+=float(wt)*d['joint_label_probabilities']
                        for k,met in enumerate(d['metrics']):
                            infidelity[k]+=float(wt)*(1-met['memory_fidelity'])
                            meter_error[k]+=float(wt)*(1-met['meter_correct_probability'])
                            joint_error[k]+=float(wt)*(1-met['both_correct_probability'])
                check(norm==1,'Marginal service normalization')
                onehit=np.mean([x['joint_label_probabilities'] for x in singles.values()],axis=0)
                # The one-hit conditional identities are independent of the age/pool.
                one_metrics=[]
                for k in range(3):
                    p=onehit[:,:,k]
                    one_metrics.append(dict(memory_fidelity=float(p[k,:].sum()),
                                            meter_correct_probability=float(p[:,k].sum()),
                                            both_correct_probability=float(p[k,k])))
                byage.append(dict(tau=cp['tau'],step=cp['step'],n=cp['n'],F=cp['F'],
                   one_update_joint_probabilities=weighted,one_update_memory_infidelity=infidelity,
                   one_update_meter_error=meter_error,one_update_joint_error=joint_error,
                   single_support_hit_joint_probabilities=onehit,single_support_hit_metrics=one_metrics,
                   one_support_hit_probability=str(Fraction(len(regs)*comb(pool-len(regs),qq-1),den))))
            phase_scan=[]
            for count in range(Q):
                h=np.array([count*(r-s) for r,s in basis],dtype=int)
                d=interrupted(h,Q)
                phase_scan.append(dict(aggregate_count=count,**d))
            gap_tables[Q][mode]=dict(single_register=singles,contexts=byage,
                                   common_phase_residue_scan=phase_scan)
    # The source marginal law and the union-only marginalization agree exactly.
    projected=Counter()
    for row in native_rows:
        subset=tuple(z for z in row['served'] if z in regs)
        projected[subset]+=row['draw_multiplicity']
    for S,mult in projected.items():
        check(mult==comb(R-len(regs),q-len(S)), 'Full native/union marginal mismatch')
        counters['native_to_quantum_marginals']+=1

    same=sum(e['token_balanced'] for e in examples)
    summary=dict(saved_representative_views=len(examples),distinct_world_architectures=len(distinct),
                 primary_protected_views=len(examples),entry_protected_views=same,
                 entry_unprotected_views=len(examples)-same,
                 epoch_targets=sorted({e['epoch_target'] for e in examples}),
                 no_new_native_trajectories=True)
    result=dict(protocol='Cell36 v1 native counting response and protected quantum-interface feasibility',
      fixture_sha256=hashlib.sha256(raw).hexdigest(),source_result_sha256=data['source_result_sha256'],
      architectural_summary=summary,architecture_audits=examples,primary_paths=paths,
      primary_checkpoint={k:v for k,v in start.items() if k!='nodes'},
      native_transition_denominator=denominator,native_transition_rows=native_rows,
      classical_successor_laws_identical_for_all_words=True,
      native_counting_can_distinguish_words=False,representative_recording_event=contact,
      late_recording_event=late_contact,
      local_projective_readout=readout,logical_label_shift=logical_shift,
      coarse_projectors=coarse_projectors,same_coarse_probabilities_for_any_input=True,
      ideal_controlled_probe=qnd,ideal_repeated_probe=repeat,
      logical_superposition_test=dict(input='|00> = sum_k Omega_k/sqrt(3)',
        reduced_memory_after_probe=reduced,fidelity_after_discarding_probe=1/3,
        coherent_inverse_recovers_input=True),
      split_interaction_sensitivity=gap_tables,validation_counts=dict(counters),
      max_numerical_errors=dict(errors),
      assumptions=dict(storage_wiring_unchanged=True,native_transition_unchanged=True,
        new_controlled_meter_coupling=True,projective_update_is_added_implementation_choice=True,
        quantum_gates_natively_compiled=False,gate_cost_or_duration_derived=False,
        mass_or_energy_operator_assigned=False,spatial_dimension_identified=False,
        changed_neutron_search=False,noise_immunity_to_arbitrary_interactions_claimed=False))
    print('CELL 36 — PROTECTED COLLECTIVE MEMORY AND A STATE-SENSITIVE INTERFACE')
    print('Frozen Cell35 storage; no new native simulation, energy assignment, or neutron-search change.')
    print('Archived assembly views:',len(examples),'distinct world/architecture relations:',len(distinct))
    print('Primary protected:',len(examples),'entry-sensitive protected:',same,'entry-sensitive failures:',len(examples)-same)
    print('Native detailed checkpoint: tau=%d, t=%d, n=%d, F=%d.'%(start['tau'],start['step'],n,forced))
    print('Exact next-event subsets:',len(native_rows),'representing',denominator,'equally likely token selections.')
    print('All three encoded words have IDENTICAL native birth/work/queue distributions.')
    print('Same endpoint comparison at tau4,194,304: cost=%d for each of the three words.'%late_contact['cost'])
    print('Actual endpoint comparison (10,11): cost=%d, repeat=%d, first-premium=%d, next_F=%d.'%
          (contact['cost'],contact['repeat_part'],contact['first_use_premium'],contact['next_F']))
    print('\nReadout/action                         correct label   original word fidelity   code-space weight')
    print('Original local projective readout        1.000000           0.333333                0.333333')
    print('ADDED coherent common-shift probe        1.000000           1.000000                1.000000')
    print('Both measurements have the SAME coarse three-outcome probabilities for every memory input.')
    print('Existing phase gate D(1/3) maps word k to k+1; subsequent storage preserves that new word.')
    print('Discarding the probe preserves the three label states, NOT every logical superposition.')
    print('\nSplit probe interaction; exactly ONE actual support-register service between its halves:')
    print(' Q   noise model       input k    meter correct    memory fidelity    both correct')
    for Q in phases:
        for model in ('primary','entry_sensitive'):
            for k,met in enumerate(gap_tables[Q][model]['contexts'][0]['single_support_hit_metrics']):
                print(f" {Q:2d}  {model:16s} {k:3d}      {met['meter_correct_probability']:.9f}    {met['memory_fidelity']:.9f}    {met['both_correct_probability']:.9f}")
    print('The completed split operation stays inside the code space, but can corrupt the encoded word.')
    print('The controlled meter is an explicit feasibility extension, not a native gate/cost derivation.')
    print('A state-dependent growth or mass response is still absent from the unchanged counting law.')
    print('PASS:',dict(counters))
    return jable(result)


